import crypto from 'node:crypto';

app.post('/login', (req, res) => {
  const { password, salt } = req.body;
  // ❌ blocks the single thread for the whole hash — every concurrent request waits
  const hash = crypto.pbkdf2Sync(password, salt, 600000, 32, 'sha256');
  res.json({ ok: verify(hash, req.user.hash) });
});

model.en:
Use the asynchronous crypto API so the hash runs on libuv's threadpool while the event loop stays free:

import crypto from 'node:crypto';
import { promisify } from 'node:util';
const pbkdf2 = promisify(crypto.pbkdf2);

app.post('/login', async (req, res, next) => {
  try {
    const { password, salt } = req.body;
    const hash = await pbkdf2(password, salt, 600000, 32, 'sha256');
    res.json({ ok: verify(hash, req.user.hash) });
  } catch (err) { next(err); }
});

Why it's right: crypto.pbkdf2 (async) hands the CPU work to libuv's threadpool, so the main thread keeps draining timers and I/O for other requests during the hash — loop lag stays sub-millisecond and concurrent requests aren't penalized. The sync variant did the opposite: it pinned the one thread for the full work. (For pure-JS CPU work with no async core API, the equivalent fix is a worker_threads pool.) Re-measure with monitorEventLoopDelay to confirm p99 dropped.

model.ru:
Используй асинхронный crypto API, чтобы хеш бежал в пуле потоков libuv, пока event loop остаётся свободным:

import crypto from 'node:crypto';
import { promisify } from 'node:util';
const pbkdf2 = promisify(crypto.pbkdf2);

app.post('/login', async (req, res, next) => {
  try {
    const { password, salt } = req.body;
    const hash = await pbkdf2(password, salt, 600000, 32, 'sha256');
    res.json({ ok: verify(hash, req.user.hash) });
  } catch (err) { next(err); }
});

Почему верно: crypto.pbkdf2 (async) отдаёт CPU-работу пулу потоков libuv, так что главный поток продолжает сливать таймеры и I/O других запросов во время хеша — задержка loop остаётся субмиллисекундной, и конкурентные запросы не штрафуются. Sync-вариант делал обратное: пришпиливал один поток на всю работу. (Для чисто-JS CPU-работы без async core API эквивалентный фикс — пул worker_threads.) Перемеряй через monitorEventLoopDelay, чтобы подтвердить, что p99 упал.
